# ============================================================ # 审核规则引擎 - 核心架构设计 # ============================================================
from abc import ABC, abstractmethod from dataclasses import dataclass, field from enum import Enum from typing import List, Dict, Optional, Any, Callable from datetime import datetime import json
# ------ 基础数据模型 ------
class Severity(Enum): """问题严重程度""" CRITICAL = "critical" # 严重：必须修改，阻止报告发出 MAJOR = "major" # 一般：需要修改，但不阻止流程 MINOR = "minor" # 轻微：建议修改 INFO = "info" # 提示：供参考
class ReviewStatus(Enum): """审核状态""" PASS = "pass" # 通过 FAIL = "fail" # 不通过 WARNING = "warning" # 警告(需人工确认) SKIP = "skip" # 跳过(规则不适用)
class RuleCategory(Enum): """规则类别""" DATA_COMPLETENESS = "data_completeness" # 数据完整性 LOGIC_CONSISTENCY = "logic_consistency" # 逻辑一致性 FORMAT_COMPLIANCE = "format_compliance" # 格式规范性 STANDARD_LIMIT = "standard_limit" # 标准限值 QC_CHECK = "qc_check" # 质控检查
@dataclass class ReviewIssue: """单个审核问题""" rule_id: str # 规则ID rule_name: str # 规则名称 category: RuleCategory # 规则类别 severity: Severity # 严重程度 status: ReviewStatus # 审核状态 message: str # 问题描述 location: str # 问题定位(如"样品信息-采样日期") expected_value: Optional[str] = None # 期望值 actual_value: Optional[str] = None # 实际值 suggestion: Optional[str] = None # 修改建议 confidence: float = 1.0 # 置信度(规则引擎默认1.0) metadata: Dict = field(default_factory=dict)
@dataclass class ReviewResult: """审核结果汇总""" report_id: str # 报告ID review_time: datetime # 审核时间 total_rules_executed: int # 执行的规则总数 total_rules_passed: int # 通过的规则数 total_rules_failed: int # 不通过的规则数 total_rules_warning: int # 警告的规则数 overall_status: ReviewStatus # 总体审核状态 overall_score: float # 总体评分(0-100) issues: List[ReviewIssue] # 问题列表 critical_count: int = 0 major_count: int = 0 minor_count: int = 0 review_duration_ms: int = 0 # 审核耗时(毫秒) engine_version: str = "1.0.0"
@property def summary(self) -> str: return (f"审核完成: 执行{self.total_rules_executed}条规则, " f"通过{self.total_rules_passed}, " f"不通过{self.total_rules_failed}, " f"警告{self.total_rules_warning}, " f"评分{self.overall_score:.1f}")
# ------ 规则基类 ------
class BaseRule(ABC): """审核规则基类"""
def __init__(self, rule_id: str, rule_name: str, category: RuleCategory, severity: Severity, description: str = "", applicable_domains: List[str] = None, applicable_categories: List[str] = None, universal: bool = True, enabled: bool = True): self.rule_id = rule_id self.rule_name = rule_name self.category = category self.severity = severity self.description = description self.applicable_domains = applicable_domains or ["ALL"] # 品类绑定：空列表表示该规则属通用集，任何品类都跑 self.applicable_categories = applicable_categories or [] # universal=False 即「品类专属」：未配置绑定的品类不跑 self.universal = universal self.enabled = enabled
def param(self, context: Dict, key: str, default=None): """取当前品类的参数覆盖（绑定表 overrides），缺省回落到规则默认值""" return (context.get("overrides") or {}).get(self.rule_id, {}).get(key, default)
def is_applicable(self, context: Dict) -> bool: """判断规则是否适用于当前报告：品类优先、领域兜底""" if not self.enabled: return False bindings = context.get("bindings") or {} if self.rule_id in bindings: # 绑定表显式决定跑不跑 return bool(bindings[self.rule_id].get("enabled", True)) if context.get("universal_only") and not self.universal: return False # 未配置品类：品类专属一律不跑 if self.applicable_categories: # 品类专属规则 cat = context.get("category", "") if cat and cat not in self.applicable_categories: return False if "ALL" in self.applicable_domains: return True return context.get("domain", "") in self.applicable_domains
@abstractmethod def execute(self, report_data: Dict, context: Dict) -> ReviewIssue: """执行审核规则""" pass
def _pass(self, message: str = "检查通过") -> ReviewIssue: return ReviewIssue( rule_id=self.rule_id, rule_name=self.rule_name, category=self.category, severity=self.severity, status=ReviewStatus.PASS, message=message, location="" )
def _fail(self, message: str, location: str = "", expected: str = None, actual: str = None, suggestion: str = None) -> ReviewIssue: return ReviewIssue( rule_id=self.rule_id, rule_name=self.rule_name, category=self.category, severity=self.severity, status=ReviewStatus.FAIL, message=message, location=location, expected_value=expected, actual_value=actual, suggestion=suggestion )
def _warning(self, message: str, location: str = "", suggestion: str = None) -> ReviewIssue: return ReviewIssue( rule_id=self.rule_id, rule_name=self.rule_name, category=self.category, severity=self.severity, status=ReviewStatus.WARNING, message=message, location=location, suggestion=suggestion )
